$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); $memoryTray=Join-Path $PSScriptRoot 'AI-Memory-Status.exe'; if (!(Test-Path -LiteralPath $memoryTray)) { throw 'The compiled status tray is missing.' }; $memoryTrayRun='"'+$memoryTray+'" --login'; $memoryRunKey=[Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Software\Microsoft\Windows\CurrentVersion\Run'); try { $memoryTrayPrevious=$memoryRunKey.GetValue('ai-memory-status',$null); if (($null -ne $memoryTrayPrevious) -and ($memoryTrayPrevious -ne $memoryTrayRun)) { throw 'An unexpected ai-memory-status startup value exists.' }; $memoryRunKey.SetValue('ai-memory-status',$memoryTrayRun,[Microsoft.Win32.RegistryValueKind]::String) } finally { $memoryRunKey.Dispose() }; $memoryShell=New-Object -ComObject WScript.Shell; $memoryLink=$memoryShell.CreateShortcut((Join-Path ([Environment]::GetFolderPath('Desktop')) 'AI Memory Tray.lnk')); $memoryLink.TargetPath=$memoryTray; $memoryLink.Arguments='--enable'; $memoryLink.Description='AI Memory live status tray'; $memoryLink.Save(); & (Join-Path $PSScriptRoot 'start_status_tray.ps1')
